const CRM_COLUMNS_V3 = [
  'conversation_id','phone','history','name','waiting_for_name','business_type','interested_service','lead_status','notes','last_message','last_ai_response','updated_at','next_action','appointment_date','budget','human_required','email','project_goal','selected_solution','pipeline_stage','last_intent','missing_fields','lead_score','conversation_summary','followup_at','followup_status','followup_count','last_bot_at','bot_muted','followup_2h_at','followup_2h_status','followup_2h_count','opt_out','handoff_at','urgency','decision_role','budget_signal','ficha_confirmada','site_shared','proposal_sent','proposal_accepted','pain_point','current_process','impact','desired_outcome','discovery_urgency','discovery_depth','discovery_done','recommended_solution','solution_confirmed','price_requested','proposal_requested','proposal_delivery_status','objection_code','handoff_reason','appointment_status','appointment_timezone','appointment_event_id','appointment_confirmation_sent','schema_version'
];
const BOOL_FIELDS = new Set(['waiting_for_name','human_required','bot_muted','opt_out','ficha_confirmada','site_shared','proposal_sent','proposal_accepted','discovery_done','solution_confirmed','price_requested','proposal_requested','appointment_confirmation_sent']);
const NUMBER_FIELDS = new Set(['lead_score','followup_count','followup_2h_count','discovery_depth']);
const PIPELINE = new Set(['nuevo','descubrimiento','calificado','propuesta','handoff','cerrado']);
const PROPOSAL = new Set(['none','requested','rendering','pending_approval','approved','rejected','sending','partially_sent','sent','failed','blocked_after_send_failure']);
const APPOINTMENT = new Set(['','requested','availability_checked','pending_confirmation','pending_approval','confirmed','cancelled','expired','failed']);

function text(value) { return String(value == null ? '' : value).replace(/\s+/g, ' ').trim(); }
function bool(value) { return value === true || value === 1 || /^(true|1|yes|si)$/i.test(text(value)); }
function parseObject(value) { if (value && typeof value === 'object' && !Array.isArray(value)) return { ...value }; try { return JSON.parse(text(value) || '{}'); } catch { return {}; } }
function parseHistory(value) { try { const rows = Array.isArray(value) ? value : JSON.parse(text(value) || '[]'); return Array.isArray(rows) ? rows.slice(-24) : []; } catch { return []; } }
function validEmail(value) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(text(value)); }

function calculateScore(row) {
  let score = 0;
  if (row.business_type) score += 10;
  if (row.project_goal) score += 10;
  if (row.pain_point) score += 10;
  if (row.current_process) score += 10;
  if (row.impact || row.discovery_urgency) score += 10;
  if (row.desired_outcome) score += 10;
  if (row.selected_solution) score += 5;
  if (row.solution_confirmed) score += 10;
  if (row.price_requested) score += 5;
  if (validEmail(row.email)) score += 5;
  if (row.proposal_requested) score += 10;
  if (row.human_required) score += 5;
  return Math.min(score, 100);
}

function normalizeCrmRow(input) {
  const source = parseObject(input?.crm_json || input?.crm || input);
  const identity = input && typeof input === 'object' ? input : {};
  const row = {};
  for (const column of CRM_COLUMNS_V3) {
    if (BOOL_FIELDS.has(column)) row[column] = bool(source[column]);
    else if (NUMBER_FIELDS.has(column)) row[column] = Number(source[column] || 0) || 0;
    else row[column] = text(source[column]);
  }
  row.conversation_id = text(identity.conversation_id || source.conversation_id);
  row.phone = text(identity.phone || source.phone);
  row.name = text(identity.name || source.name);
  row.email = validEmail(identity.email || source.email) ? text(identity.email || source.email) : '';
  row.history = JSON.stringify(parseHistory(identity.history_json || source.history));
  row.conversation_summary = text(source.conversation_summary).slice(0, 420);
  row.schema_version = '3.0';
  row.updated_at = text(source.updated_at || identity.updated_at || new Date().toISOString());
  row.pipeline_stage = PIPELINE.has(text(source.pipeline_stage)) ? text(source.pipeline_stage) : 'nuevo';
  row.proposal_delivery_status = PROPOSAL.has(text(source.proposal_delivery_status)) ? text(source.proposal_delivery_status) : 'none';
  row.appointment_status = APPOINTMENT.has(text(source.appointment_status)) ? text(source.appointment_status) : '';
  row.proposal_sent = row.proposal_sent && row.proposal_delivery_status === 'sent';
  row.proposal_accepted = row.proposal_accepted && row.proposal_sent;
  row.lead_score = calculateScore(row);
  row.lead_status = row.lead_score >= 70 ? 'caliente' : row.lead_score >= 40 ? 'tibio' : 'frio';
  if (!row.conversation_id) throw new Error('CRM_CONVERSATION_ID_REQUIRED');
  return row;
}

function evaluateExistingRows(rows, canonical) {
  const matching = (rows || []).map((item) => item && item.json ? item.json : item).filter((row) => text(row?.conversation_id) === canonical.conversation_id);
  if (matching.length > 1) throw new Error('CRM_DUPLICATE_CONVERSATION');
  const rowNumber = matching.length === 1 ? Number(matching[0].row_number || 0) : 0;
  return { ...canonical, crm_operation: rowNumber > 0 ? 'update' : 'append', row_number: rowNumber, duplicate_count: matching.length };
}


const input = $input.first()?.json || {};
const row = normalizeCrmRow(input);
return [{ json: { ...row, dry_run: input.dry_run === true || String(input.dry_run).toLowerCase() === 'true', source_hash: String(input.source_hash || ''), environment: String(input.environment || 'staging') } }];

